export const metadata: Metadata = {
  title: 'Create Next App',
  description: 'Generated by create next app'
};

export default function RootLayout({
  children
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}
```

### 7. Key Dependencies

From `package.json`:
- **next**: ^16.2.0-canary.41 (Canary)
- **react**: 19.1.0 (Latest)
- **react-dom**: 19.1.0
- **@ai-sdk/react**: 2.0.0-beta.28 (AI/ML integration)
- **ai**: 5.0.59 (Core AI SDK)
- **zod**: ^4.0.10 (Schema validation)
- **@modelcontextprotocol/sdk**: ^1.17.0 (Model Context Protocol)

### Summary

This is a **minimal Next.js 16 canary project** using the App Router with server components. The established pattern is:
- Server components with async/await
- Native fetch() API for data retrieval
- Parallel data fetching with Promise.all()
- Error boundaries with fallback mock data
- NO external data fetching libraries (SWR, React Query, etc.)
- NO API routes or utility functions currently implemented

The Dashboard component is a placeholder awaiting implementation that should follow the same server component async pattern demonstrated in page.tsx.

